parameters.jsCode:
const anamneseRes = JSON.parse($('Anamnese (Gemini 3.5 Flash Lite)').item.json.candidates[0].content.parts[0].text);
const perfil = anamneseRes.dados_atualizados;

const peso = parseFloat(perfil.peso);
const altura = parseFloat(perfil.altura);
const idade = parseInt(perfil.idade);
const sexo = (perfil.sexo || '').toLowerCase();
const objetivo = (perfil.objetivo || '').toLowerCase();
const nivelAtividade = perfil.nivel_atividade || 'moderado';

// Mifflin-St Jeor
let tmb = (10 * peso) + (6.25 * altura) - (5 * idade);
tmb += (sexo.includes('m') || sexo.includes('homem') || sexo.includes('masculino')) ? 5 : -161;

const fatores = {
  sedentario: 1.2,
  leve: 1.375,
  moderado: 1.55,
  intenso: 1.725,
  muito_intenso: 1.9
};
const fator = fatores[nivelAtividade] || 1.55;
const get = tmb * fator;

let caloriasAlvo = get;
if (objetivo.includes('emagrec') || objetivo.includes('perda')) {
  caloriasAlvo -= 500;
} else if (objetivo.includes('hipertrofia') || objetivo.includes('ganho')) {
  caloriasAlvo += 300;
}

const proteinaGrams = peso * 2.0;
const gorduraGrams = peso * 1.0;
const proteinaKcal = proteinaGrams * 4;
const gorduraKcal = gorduraGrams * 9;
const carboKcal = Math.max(0, caloriasAlvo - (proteinaKcal + gorduraKcal));
const carboGrams = carboKcal / 4;

return {
  json: {
    perfil,
    calculos: {
      tmb: Math.round(tmb),
      get: Math.round(get),
      calorias_alvo: Math.round(caloriasAlvo),
      macros: {
        proteina_g: Math.round(proteinaGrams),
        gordura_g: Math.round(gorduraGrams),
        carboidrato_g: Math.round(carboGrams)
      }
    }
  }
};

